KG42.register("rules-4626b12b18dbe2edd4b350e0",{"id":"04-energy_collectives::v141-c-R016","paper":"04-energy_collectives","record":{"rule_id":"v141-c-R016","mechanism_id":"v141-a-M02","name":"Inter-area market clearing","process_stage":"clearing","market_meaning":"The inter-neighbourhood allocation model includes relative geographical transaction costs weighted by the magnitudes of energy flows on the connecting lines. Scope: Inter-neighbourhood allocations within the illustrated three-neighbourhood energy collective. Condition: When the geographical-preference formulation is adopted. Inter-neighbourhood allocations must satisfy the specified balances for N1 and N2: each neighbourhood's aggregate community exchange equals the signed sum of its connecting-line flows. Scope: The N1 and N2 balance restrictions in the illustrated collective comprising neighbourhoods N1, N2 and N3. Condition: When the three-neighbourhood geographical-preference formulation is adopted.","independence_rationale":"Relations governed by the approved function clearing.inter_area under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.inter_area"],"E":[],"omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Inter-neighbourhood allocations within the illustrated three-neighbourhood energy collective. | The N1 and N2 balance restrictions in the illustrated collective comprising neighbourhoods N1, N2 and N3.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30"]},"x":[{"variable_id":"v141-c-R016-x-qj","symbol":"q_j","meaning":"Energy imported by prosumer j from the community (community-level exchange quantity), used in the neighbourhood balance sums.","kind":"operational","domain":"unspecified (source lists q_j among decision variables in the exchange problem; no explicit domain/bounds in the supplied evidence)","unit":null,"indices":["j = 1, ..., n","j belongs to N_1, N_2 or N_3"],"evidence_ids":["v141-b-g01-E30","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-v","symbol":"\\boldsymbol{v}","meaning":"Vector of directed energy flows on the lines connecting the neighbourhoods: v = (v_{12}, v_{13}, v_{23}).","kind":"operational","domain":"unspecified (source defines v as energy flows; no explicit domain in the supplied evidence)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e09","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-v12","symbol":"v_{12}","meaning":"Directed energy flow on the line connecting neighbourhoods N_1 and N_2.","kind":"operational","domain":"unspecified (source defines v_12 as an energy flow; no explicit domain in the supplied evidence)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e09","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-v13","symbol":"v_{13}","meaning":"Directed energy flow on the line connecting neighbourhoods N_1 and N_3.","kind":"operational","domain":"unspecified (source defines v_13 as an energy flow; no explicit domain in the supplied evidence)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e09","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-v23","symbol":"v_{23}","meaning":"Directed energy flow on the line connecting neighbourhoods N_2 and N_3.","kind":"operational","domain":"unspecified (source defines v_23 as an energy flow; no explicit domain in the supplied evidence)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e09","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-qimp","symbol":"q_{imp}","meaning":"Total energy imported by the community from the market or system operator, appearing in the geographical-preference interface objective g.","kind":"operational","domain":"unspecified (source uses q_imp as a global variable in g; no explicit domain in the supplied evidence for this rule)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E30","v141-b-g02-e10"]},{"variable_id":"v141-c-R016-x-qexp","symbol":"q_{exp}","meaning":"Total energy exported by the community to the market or system operator, appearing in the geographical-preference interface objective g.","kind":"operational","domain":"unspecified (source uses q_exp as a global variable in g; no explicit domain in the supplied evidence for this rule)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E30","v141-b-g02-e10"]}],"theta":[{"parameter_id":"v141-c-R016-theta-gamma-geo","symbol":"\\gamma_{geo}","meaning":"Vector of relative geographical transaction costs between neighbourhoods: (\\gamma_{geo,12}, \\gamma_{geo,13}, \\gamma_{geo,23}).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["12, 13, 23"],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e09","v141-b-g02-e10"]},{"parameter_id":"v141-c-R016-theta-gamma-imp","symbol":"\\gamma_{imp}","meaning":"Penalty factor / price the community is willing to pay for importing energy from the market or system operator; it multiplies q_imp in the geographical-preference interface objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E30","v141-b-g02-e10"]},{"parameter_id":"v141-c-R016-theta-gamma-exp","symbol":"\\gamma_{exp}","meaning":"Penalty factor / price the community is willing to receive for exporting energy to the market or system operator; it multiplies q_exp in the geographical-preference interface objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E30","v141-b-g02-e10"]}],"phi":[{"constraint_id":"v141-c-R016-C001","kind":"mathematical","role":"core","statement":"The inter-neighbourhood allocation model includes relative geographical transaction costs weighted by the magnitudes of energy flows on the connecting lines. Scope: Inter-neighbourhood allocations within the illustrated three-neighbourhood energy collective. Condition: When the geographical-preference formulation is adopted.","expression":"g(q_{imp}, q_{exp}) = \\gamma_{imp} q_{imp} + \\gamma_{exp} q_{exp} + \\gamma_{geo}^{\\top} |\\boldsymbol{v}|","formalization_origin":"source","template_id":null,"members":["clearing.inter_area"],"variable_refs":["v141-c-R016-x-qimp","v141-c-R016-x-qexp","v141-c-R016-x-v"],"parameter_refs":["v141-c-R016-theta-gamma-imp","v141-c-R016-theta-gamma-exp","v141-c-R016-theta-gamma-geo"],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e10"]},{"constraint_id":"v141-c-R016-C002","kind":"mathematical","role":"core","statement":"Inter-neighbourhood allocations must satisfy the specified balances for N1 and N2: each neighbourhood's aggregate community exchange equals the signed sum of its connecting-line flows. Scope: The N1 and N2 balance restrictions in the illustrated collective comprising neighbourhoods N1, N2 and N3. Condition: When the three-neighbourhood geographical-preference formulation is adopted.","expression":"\\sum_{j \\in N_1} q_j = + v_{12} + v_{13},\\quad \\sum_{j \\in N_2} q_j = - v_{12} + v_{23}","formalization_origin":"source","template_id":null,"members":["clearing.inter_area"],"variable_refs":["v141-c-R016-x-qj","v141-c-R016-x-v12","v141-c-R016-x-v13","v141-c-R016-x-v23"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E29","v141-b-g01-E30","v141-b-g02-e10"]}],"pi":[{"evidence_id":"v141-b-g01-E29","location":{"location_id":"src-dfa28329fc-p05-c1r4__v141-a-M02-coordination","page":5,"printed_page":"3998","section":"III. The Role of Community Manager","anchor_text":"g p , p g , off- and connected to the grid [6], is only one possible conﬁg- w uration, but more gene","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Energy collectives are to be envisaged as a market construct and not related to a certain positioning on the electric power grid. In practice, this means that operation on a micro-grid, both off- and connected to the grid [6], is only one possible configuration, but more generally such communities may be formed irrespective of grid connection and geographical location. The use of distribution (or transmission for longer distances) networks for community trades results in additional grid costs including several parameters, e.g. geographical distance and lines congestion. We include these additional costs by investigating a setup where an energy collective is formed by prosumers from three different neighbourhoods, N1, N2, N3. We model this system by splitting (1c) in three sub-communities and by defining energy flows, v = (v_12, v_13, v_23), on each line connecting the neighbourhoods, as depicted in Fig. 2. We include geographical differentiation as relative transaction costs gamma_geo = (gamma_geo,12, gamma_geo,13, gamma_geo,23)."},{"evidence_id":"v141-b-g01-E30","location":{"location_id":"src-dfa28329fc-p05-c2r1__v141-a-M02-coordination","page":5,"printed_page":"3998","section":"III. The Role of Community Manager","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 γgeo = (γgeo,12, γgeo,13, γgeo,23","equation_id":"(12)","figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"gamma_geo = (gamma_geo,12, gamma_geo,13, gamma_geo,23). It follows that  g(q_imp, q_exp) = gamma_imp q_imp + gamma_exp q_exp + gamma_geo^T |v|  sum_{j in N1} q_j = + v_12 + v_13  sum_{j in N2} q_j = - v_12 + v_23  sum_{j in N3} q_j = - v_13 - v_13   (12)  This formulation allows to represent technical constraints, typical of power flow analysis, in the form of spatial and temporal varying grid tariffs. This becomes fundamental in view of a possible integration of energy collectives in the current system operation. Furthermore, the collective can be fragmented to the extreme, i.e., to single prosumer, accounting for individual trades, as in [19]. In this way, the energy collective becomes a supervised version of a fully peer-to-peer economic dispatch."},{"evidence_id":"v141-b-g02-e09","location":{"location_id":"src-dfa28329fc-p05-c1r4__v141-a-M02-coordination","page":5,"printed_page":"3998","section":"III. The Role of Community Manager","anchor_text":"g p , p g , off- and connected to the grid [6], is only one possible conﬁg- w uration, but more gene","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"unknown"},"source_text":"E. Geographical Preferences\n\nEnergy collectives are to be envisaged as a market construct and not related to a certain positioning on the electric power grid. In practice, this means that operation on a micro-grid, both off- and connected to the grid [6], is only one possible configuration, but more generally such communities may be formed irrespective of grid connection and geographical location. The use of distribution (or transmission for longer distances) networks for community trades results in additional grid costs including several parameters, e.g. geographical distance and lines congestion.\nWe include these additional costs by investigating a setup where an energy collective is formed by prosumers from three different neighbourhoods, N_{1}, N_{2}, N_{3}. We model this system by splitting (1c) in three sub-communities and by defining energy flows, \\boldsymbol{v} = (v_{12}, v_{13}, v_{23}), on each line connecting the neighbourhoods, as depicted in Fig. 2. We include geographical differentiation as relative transaction costs"},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-dfa28329fc-p05-c2r1__v141-a-M02-coordination","page":5,"printed_page":"3998","section":"III. The Role of Community Manager","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 γgeo = (γgeo,12, γgeo,13, γgeo,23","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"\\gamma_{geo} = (\\gamma_{geo,12}, \\gamma_{geo,13}, \\gamma_{geo,23}). It follows that\n\ng(q_{imp}, q_{exp}) = \\gamma_{imp}q_{imp} + \\gamma_{exp}q_{exp} + \\boldsymbol{\\gamma}_{geo}^{T}|\\boldsymbol{v}|\n\n\\sum_{j \\in N_1} q_j = + v_{12} + v_{13}\n\\sum_{j \\in N_2} q_j = - v_{12} + v_{23}\n\\sum_{j \\in N_3} q_j = - v_{13} - v_{13}                    (12)"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-coordination"],"extras":{"decision_anchor":"clearing.inter_area","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E29","quote":"We model this system by splitting (1c) in three sub-communities and by defining energy flows, v = (v_12, v_13, v_23), on each line connecting the neighbourhoods, as depicted in Fig. 2. We include geographical differentiation as relative transaction costs gamma_geo = (gamma_geo,12, gamma_geo,13, gamma_geo,23)."},{"evidence_id":"v141-b-g01-E30","quote":"g(q_imp, q_exp) = gamma_imp q_imp + gamma_exp q_exp + gamma_geo^T |v|"}],[{"evidence_id":"v141-b-g01-E29","quote":"We model this system by splitting (1c) in three sub-communities and by defining energy flows, v = (v_12, v_13, v_23), on each line connecting the neighbourhoods, as depicted in Fig. 2."},{"evidence_id":"v141-b-g01-E30","quote":"sum_{j in N1} q_j = + v_12 + v_13  sum_{j in N2} q_j = - v_12 + v_23"}]],"C2_formalization":{"graph_sha256":"3288619f253985d9f1175d87ed375c53dbc4faa325c0db8e50f4cd2ca499505f","applicability":"formalized","reason":"Source eq. (12) supplies explicit expressions for the geographical-preference inter-neighbourhood cost term and for the N1/N2 neighbourhood balances, so the core constraints are formalized from the supplied unreviewed B evidence. Units, domains, and the unresolved N3 balance are left unspecified and are requested for C.1/B revision.","bindings":[{"object_id":"v141-c-R016-x-qj","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"q_j is the prosumer community-exchange variable summed in the N_1 and N_2 balance equations that define inter-area clearing under the frozen rule; clearing.inter_area is the only frozen node and E is empty."},{"object_id":"v141-c-R016-x-v","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"v is defined in the source as the vector of inter-neighbourhood line flows used by the geographical-cost term in clearing.inter_area; no frozen edges exist for this rule."},{"object_id":"v141-c-R016-x-v12","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"v_12 is a component of the inter-neighbourhood flow vector used in clearing.inter_area balances and the geographical-cost term; no frozen edges exist."},{"object_id":"v141-c-R016-x-v13","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"v_13 is a component of the inter-neighbourhood flow vector used in clearing.inter_area balances and the geographical-cost term; no frozen edges exist."},{"object_id":"v141-c-R016-x-v23","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"v_23 is a component of the inter-neighbourhood flow vector used in clearing.inter_area balances and the geographical-cost term; no frozen edges exist."},{"object_id":"v141-c-R016-x-qimp","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"q_imp appears in the geographical-preference interface objective g for inter-area clearing; it is bound to the frozen clearing.inter_area node."},{"object_id":"v141-c-R016-x-qexp","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"q_exp appears in the geographical-preference interface objective g for inter-area clearing; it is bound to the frozen clearing.inter_area node."},{"object_id":"v141-c-R016-theta-gamma-geo","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"gamma_geo parameterizes the geographical transaction-cost term in clearing.inter_area; no frozen edges exist for this rule."},{"object_id":"v141-c-R016-theta-gamma-imp","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"gamma_imp is the import price/penalty parameter in the interface objective used by clearing.inter_area; no frozen edges exist."},{"object_id":"v141-c-R016-theta-gamma-exp","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"gamma_exp is the export price/penalty parameter in the interface objective used by clearing.inter_area; no frozen edges exist."},{"object_id":"v141-c-R016-C001","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"The formalized geographical-cost equation is a core clearing.inter_area constraint; edge_ids is empty because the frozen rule has no edges."},{"object_id":"v141-c-R016-C002","node_ids":["clearing.inter_area"],"edge_ids":[],"rationale":"The formalized N_1 and N_2 neighbourhood balances are core clearing.inter_area constraints; edge_ids is empty because the frozen rule has no edges."}],"revision_requests":["Source eq. (12)'s third sub-community balance is printed as `\\sum_{j \\in N_3} q_j = - v_{13} - v_{13}`; the repeated `v_{13}` is unresolved. B re-extraction should verify whether the intended expression is `-v_{13} - v_{23}` or another form before N3 is formalized.","The frozen graph for v141-c-R016 has no edges. If inter-neighbourhood clearing should link `clearing.inter_area` to other nodes (e.g. `product.local_energy`, `execution.energy_trade`), C.1 must add explicit edges; none are asserted here.","Units and explicit numeric values are not supplied for `\\gamma_{geo}`, `\\gamma_{imp}`, `\\gamma_{exp}`, `q_j`, `q_{imp}`, `q_{exp}`, or `v_{12}, v_{13}, v_{23}`; these remain unspecified rather than inferred.","The supplied B evidence does not explicitly state the domain/sign convention of `q_j` in the neighbourhood balances; the nomenclature calls it energy imported by prosumer j while the source sums it to zero, so signedness and domain require source clarification."]},"C2_delivery":{"raw_sha256":"08552a29f6f74502f4186e48d1690a9d6a529cff643c440234bac70407fc67a8","delivery_payload_sha256":"d7f793371d6b8abfe3d918d9415133dcfcbe3896f130659a45cc0e7e9d12858e","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"3288619f253985d9f1175d87ed375c53dbc4faa325c0db8e50f4cd2ca499505f","scientific_correctness_verified":false}},"quarantined_references":[]}});
